#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    auto do_op = [&](int x, int y){
        assert(x>=1 && y>=1 && x+y<n);
        ops.push_back({x,y});
        vector<int> np;
        for(int i=n-y;i<n;i++) np.push_back(p[i]);
        for(int i=x;i<n-y;i++) np.push_back(p[i]);
        for(int i=0;i<x;i++) np.push_back(p[i]);
        p=np;
    };

    for(int placed=0; placed<n; placed++){
        int pos=-1;
        for(int i=placed;i<n;i++) if(p[i]==placed+1){pos=i;break;}
        if(pos==placed) continue;

        int rem = n - placed; // remaining elements to sort
        if(rem <= 2){
            // Only 2 elements left and they're swapped
            // p[placed] and p[placed+1] need swapping
            // We need an operation on the full array... 
            // x=placed+1, y=1 => suffix=p[n-1], middle=p[placed+1..n-2], prefix=p[0..placed]
            // This moves p[n-1] to front, p[0..placed] to end
            // For rem=2: n-1=placed+1, placed=n-2
            // x=n-1, y=1: x+y=n, not valid
            // x=1, y=1: swap first and last, keep middle
            if(n>=3){
                do_op(1,1);
                // Check if now sorted from placed onwards
                bool ok=true;
                for(int i=placed;i<n;i++) if(p[i]!=i+1){ok=false;break;}
                if(ok) continue;
                // May need more work - restart this placed
                placed--;
                continue;
            }
            break;
        }

        // Step 1: Move element from pos to n-1
        if(pos != n-1){
            // x=pos-placed+1 (relative to placed, but ops are on full array)
            // suffix = p[pos+1..n-1] has n-1-pos elements. But we need pos+1..n-1 to wrap.
            // x=pos+1, y=n-1-pos: x+y=n, invalid
            // x=pos+1, y=n-2-pos (if pos<=n-3): moves p[pos+2..n-1]+p[pos+1]+p[0..pos], element at pos goes to n-1
            if(pos <= n-3){
                do_op(pos+1, n-2-pos);
            } else {
                // pos=n-2: do_op(1,1) to shuffle, then retry
                do_op(1,1);
                placed--;
                continue;
            }
        }
        // Now target element is at position n-1
        // Step 2: Move from n-1 to position placed
        // suffix goes to positions 0..y-1. Element at n-1 goes to y-1. Set y=placed+1.
        // x=1, y=placed+1, x+y=placed+2. Need placed+2<n => placed<n-2 (true since rem>=3)
        do_op(1, placed+1);
    }

    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
